const DISCURSIVAS = [
  { f: "Lista 1 – Q18", t: "threads", q: "Explique qual a diferença entre execução síncrona e assíncrona.",
    r: "Na execução <b>síncrona</b>, cada operação precisa terminar antes da próxima começar: quem chamou fica <b>bloqueado</b> esperando o resultado (ex.: Thread.Sleep, .Result). Na execução <b>assíncrona</b>, a operação é iniciada e o programa <b>não fica parado esperando</b>: a thread é liberada para fazer outras tarefas e, quando o resultado chega, a execução continua de onde parou (em C#: async/await com Task). Ex.: enviar várias transações PIX e continuar atendendo usuários enquanto as respostas não chegam.",
    k: ["bloqueia / espera terminar", "não bloqueia a thread", "continua outras tarefas", "async/await / Task", "exemplo (PIX, API, banco)"] },
  { f: "Lista 1 – Q20", t: "threads", q: "Por que a execução assíncrona não bloqueia a execução na thread principal?",
    r: "Porque o <b>await</b> não fica parado esperando: o compilador transforma o método async em uma <b>máquina de estado</b>; ao encontrar um await de uma tarefa não concluída, ele <b>registra uma continuação</b> e <b>devolve o controle imediatamente</b> a quem chamou. A thread fica livre para outras tarefas. A espera de I/O (rede, disco, banco) é feita pelo sistema/runtime, e quando a Task termina, a continuação é executada (geralmente na mesma thread/contexto, a menos que se use ConfigureAwait(false)), usando o <b>thread pool</b>.",
    k: ["máquina de estado", "await registra continuação", "devolve o controle", "thread fica livre", "thread pool / Task concluída retoma"] },
  { f: "Lista 1 – Q22", t: "comunicacao", q: "Qual papel tem a API em um sistema distribuído? Cite pelo menos um framework de exemplo de API REST.",
    r: "A <b>API</b> (Application Programming Interface) é o <b>conjunto de regras, protocolos e interfaces</b> que permite que sistemas diferentes se comuniquem e acessem funcionalidades/dados de outro software <b>sem conhecer sua implementação interna</b>. Em um sistema distribuído ela é o 'contrato' entre os serviços (ex.: serviço de Pedidos consulta o Catálogo via API REST sobre HTTP, trocando JSON). Frameworks: <b>Flask</b> (Python), Django REST Framework, Node.js + Express, Spring Boot (Java), ASP.NET Core Web API (C#).",
    k: ["regras/interfaces/contrato", "integração entre sistemas", "não precisa conhecer implementação", "HTTP/JSON", "framework (Flask, Express, Spring Boot...)"] },
  { f: "Lista 1 – Q23", t: "threads", q: "Por que seria importante executar uma operação assíncrona em um banco de dados para fazer uma consulta?",
    r: "Consultas ao banco podem <b>demorar</b> (banco remoto, grande volume de dados, rede). Se forem síncronas, a thread fica <b>bloqueada</b> sem fazer nada, desperdiçando recursos; em um servidor com muitas requisições isso pode <b>esgotar o thread pool</b> e travar a aplicação (ou congelar a interface, em apps desktop). Com <b>await</b> (Entity Framework: ToListAsync; Dapper: QueryAsync) a thread é liberada enquanto o banco responde, permitindo atender mais usuários com menos recursos — mais <b>escalabilidade e responsividade</b>.",
    k: ["consulta pode demorar", "evita bloquear a thread", "não esgota o thread pool", "escalabilidade/responsividade", "EF Core / Dapper async"] },
  { f: "Lista 1 – Q24", t: "threads", q: "Conceitue paralelismo e concorrência.",
    r: "<b>Concorrência</b> é a capacidade de lidar com várias tarefas 'ao mesmo tempo', mas <b>não necessariamente no mesmo instante</b>: as tarefas são <b>intercaladas</b> (o processador alterna entre elas). Pode ocorrer até com um único núcleo e é ideal quando há esperas (disco, rede, usuário). <b>Paralelismo</b> é a execução de várias tarefas <b>no mesmo instante</b>, em <b>núcleos/processadores diferentes</b>; exige hardware multicore e é ideal para tarefas pesadas de CPU (cálculos, renderização). Resumo: concorrência = lidar com muitas coisas; paralelismo = fazer muitas coisas ao mesmo tempo.",
    k: ["concorrência = intercalada", "pode ser 1 núcleo / I/O", "paralelismo = simultâneo", "múltiplos núcleos", "CPU-bound"] },
  { f: "Extra", t: "sincronizacao", q: "Diferencie Mutex e Semáforo e dê um exemplo de uso de cada.",
    r: "<b>Mutex</b> garante <b>exclusão mútua</b>: apenas <b>uma</b> thread/processo possui o recurso por vez (local ou nomeado/inter-processo). Ex.: escrita em um arquivo, acesso exclusivo a hardware, impedir duas instâncias do programa. <b>Semáforo</b> mantém um <b>contador</b> que permite até <b>N</b> acessos simultâneos; quando chega a zero, as próximas threads esperam até um Release(). Ex.: limitar 10 conexões a um serviço, pool de conexões ao banco, produtor/consumidor com buffer limitado. Semáforo binário (0/1) equivale a um mutex.",
    k: ["mutex = 1 por vez", "semáforo = contador N", "exemplo mutex", "exemplo semáforo", "binário = mutex"] },
  { f: "Extra", t: "eventos", q: "Diferencie ManualResetEvent e AutoResetEvent. Quando usar cada um?",
    r: "Ambos são mecanismos de <b>sinalização</b> com estados sinalizado/não sinalizado (WaitOne, Set, Reset). No <b>ManualResetEvent</b>, Set() libera <b>todas</b> as threads aguardando e o evento <b>permanece sinalizado</b> até alguém chamar Reset() (risco: esquecer o Reset). Use quando várias threads devem avançar juntas — ex.: 'a inicialização terminou, todos podem começar'. No <b>AutoResetEvent</b>, Set() libera <b>apenas uma</b> thread e o evento <b>volta automaticamente</b> a não sinalizado. Use quando cada sinal deve ser consumido por um único consumidor — ex.: 'chegou uma unidade de trabalho'. Pergunta-chave: quantas threads devem avançar quando o sinal chegar?",
    k: ["sinalização", "Manual: libera todas / fica aberto", "precisa Reset()", "Auto: libera uma / reseta sozinho", "exemplos de uso"] },
  { f: "Extra", t: "monitor", q: "O que é uma race condition? Explique como o Monitor (ou lock) a resolve, usando o exemplo do estoque.",
    r: "<b>Race condition</b> ocorre quando o resultado depende da ordem/tempo de execução de threads que acessam um recurso compartilhado sem sincronização. Ex.: estoque = 10, duas threads querem vender 7. Sem proteção, ambas <b>leem 10</b> antes de qualquer uma atualizar, ambas aprovam a venda, e o sistema vende 14 itens que não existem (estoque inconsistente). Com <b>Monitor.Enter/Exit</b> (ou lock) sobre o mesmo objeto de bloqueio, apenas uma thread por vez executa a seção crítica (ler → verificar → atualizar). A segunda só entra depois que a primeira sai, lê 3 e recusa a venda. O Exit deve ficar em um <b>finally</b> para liberar mesmo com exceção.",
    k: ["definição race condition", "exemplo estoque 10 / venda 7", "seção crítica", "uma thread por vez / mesmo objeto", "Exit no finally"] },
  { f: "Extra", t: "principios", q: "Explique o Teorema CAP.",
    r: "O Teorema CAP diz que um sistema distribuído não consegue garantir ao mesmo tempo as três propriedades: <b>Consistência</b> (todas as réplicas com o mesmo dado), <b>Disponibilidade</b> (todo pedido recebe resposta) e <b>Tolerância a Partições</b> (continua funcionando mesmo com falha de comunicação entre nós). É preciso escolher <b>2</b>. Como partições de rede acontecem, na prática o trade-off é entre consistência forte e disponibilidade (muitos sistemas escolhem disponibilidade + <b>consistência eventual</b>).",
    k: ["Consistência", "Disponibilidade", "Tolerância a partições", "escolhe 2", "trade-off / eventual"] },
  { f: "Extra", t: "comunicacao", q: "Compare WebSocket com HTTP/API REST.",
    r: "<b>HTTP/REST</b> é baseado em <b>requisição-resposta</b>: o cliente pede, o servidor responde e a conexão é encerrada; o servidor não envia dados por iniciativa própria. Ideal para consultas pontuais (dados, login). <b>WebSocket</b> faz um <b>handshake</b> inicial via HTTP (Upgrade: websocket) e depois mantém uma <b>conexão TCP persistente e bidirecional</b>: cliente e servidor enviam dados a qualquer momento, com baixa latência e menos overhead. Ideal para tempo real (chats, jogos, dashboards IoT). Segurança: https:// e wss:// (TLS/SSL).",
    k: ["REST = requisição-resposta", "conexão fecha", "WebSocket = persistente bidirecional", "handshake HTTP Upgrade", "casos de uso"] },
  { f: "Extra", t: "comunicacao", q: "Explique o funcionamento do MQTT e dê um exemplo.",
    r: "<b>MQTT</b> (Message Queuing Telemetry Transport) é um protocolo <b>leve</b>, sobre TCP/IP, no modelo <b>publish/subscribe</b>, feito para dispositivos com poucos recursos e redes instáveis (IoT). Tem três papéis: <b>Broker</b> (servidor que gerencia tópicos e encaminha mensagens), <b>Publisher</b> (publica em um tópico) e <b>Subscriber</b> (recebe as mensagens dos tópicos inscritos). Ex.: um sensor de temperatura (ESP32) publica em <i>casa/sala/temperatura</i>; um app inscrito nesse tópico recebe as leituras. Produtor e consumidor ficam desacoplados.",
    k: ["leve / IoT", "pub/sub", "Broker", "Publisher / Subscriber", "exemplo com tópico"] },
];
